def gen(rng):
    def fmt(bed, ks):
        return f"{len(bed)}\n" + ' '.join(map(str, bed)) + f"\n{len(ks)}\n" + ' '.join(map(str, ks))
    def rbed(n, p):
        bed = []
        for i in range(n):
            if i > 0 and bed[-1] == 1:
                bed.append(0)
            else:
                bed.append(1 if rng.random() < p else 0)
        return bed
    tests = [fmt([0], [0, 1, 2]), fmt([1], [0, 1]), fmt([0, 0], [1, 2]), fmt([1, 0, 0, 0, 1], [0, 1, 2]),
             fmt([0] * 5, [1, 2, 3, 4]), fmt([0, 1, 0], [0, 1]), fmt([1, 0, 1, 0, 1], [1]), fmt([0, 0, 1], [1, 2])]
    for _ in range(14):
        n = rng.randint(1, 12)
        bed = rbed(n, rng.choice([0.1, 0.3, 0.5]))
        ks = [rng.randint(0, n) for _ in range(rng.randint(1, 8))]
        tests.append(fmt(bed, ks))
    N = 100000
    tests.append(fmt([0] * N, [rng.randint(0, N) for _ in range(N)]))
    tests.append(fmt([0] * N, [(N + 1) // 2 + rng.randint(-2, 2) for _ in range(N)]))
    tests.append(fmt(rbed(N, 0.2), [rng.randint(0, N // 3) for _ in range(N)]))
    tests.append(fmt([1, 0] * (N // 2), [rng.randint(0, 3) for _ in range(N)]))
    return tests

